# setup_sh: build fixtures in $W (current dir), launch live deserialization service
set -e
W="$(pwd)"

cat > server.py <<'PY'
import json, secrets, threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

# Secret lives only in memory of this process. Never written to disk.
class SecretVault:
    def __init__(self):
        self.api_key = secrets.token_hex(16)

VAULT = SecretVault()

# ---- Registered message classes (deserialization allow-map) ----
# Intended, benign type used by legitimate clients.
class EchoMessage:
    def __init__(self, fields):
        self.text = fields.get("text", "")
    def render(self):
        return {"echo": self.text}

class UpperMessage:
    def __init__(self, fields):
        self.text = fields.get("text", "")
    def render(self):
        return {"upper": self.text.upper()}

# GADGET: also present in the registry, reachable purely by name via $type.
# Its render() reads server-side in-memory state. Not meant for clients.
class SecretHolder:
    def __init__(self, fields):
        self._vault = VAULT
    def render(self):
        return {"api_key": self._vault.api_key}

REGISTRY = {
    "app.EchoMessage": EchoMessage,
    "app.UpperMessage": UpperMessage,
    "app.SecretHolder": SecretHolder,
}

def deserialize(msg):
    # Vulnerable pattern: type metadata in the payload selects the class.
    tname = msg.get("$type", "app.EchoMessage")
    cls = REGISTRY.get(tname)
    if cls is None:
        return {"error": "unknown type"}
    obj = cls(msg)          # attacker-controlled type instantiated by name
    return obj.render()     # gadget method invoked

class Handler(BaseHTTPRequestHandler):
    def log_message(self, *a):
        pass
    def do_POST(self):
        if self.path != "/msg":
            self.send_response(404); self.end_headers(); return
        try:
            n = int(self.headers.get("Content-Length", "0"))
            body = self.rfile.read(n)
            msg = json.loads(body.decode("utf-8"))
            if not isinstance(msg, dict):
                raise ValueError("object expected")
            out = deserialize(msg)
        except Exception as e:
            out = {"error": str(e)}
        data = json.dumps(out).encode("utf-8")
        self.send_response(200)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)

def main():
    srv = ThreadingHTTPServer(("127.0.0.1", 0), Handler)
    port = srv.server_address[1]
    with open("port.txt", "w") as f:
        f.write(str(port))
    srv.serve_forever()

if __name__ == "__main__":
    main()
PY

# Legit client doc, so the intended usage is documented (no secret here).
cat > README.txt <<'TXT'
Message service. POST JSON to http://127.0.0.1:<port.txt>/msg
A message is a JSON object. Optional "$type" selects the message class
(default "app.EchoMessage"). Registered types:
  app.EchoMessage   {"text": "..."}  -> {"echo": "..."}
  app.UpperMessage  {"text": "..."}  -> {"upper": "..."}
Example:
  {"$type": "app.EchoMessage", "text": "hi"}
TXT

rm -f port.txt
nohup python3 server.py >/dev/null 2>&1 &
echo $! > server.pid

# wait for the server to publish its port
i=0
while [ ! -s port.txt ]; do
  i=$((i+1))
  [ "$i" -gt 100 ] && { echo "server did not start" >&2; exit 1; }
  sleep 0.1
done
